    try:
        for line in open(f):
            m=re.match(r'\s*(?:public\s+)?import\s+(AlgebraicJacobian[\w.]*)',line)
            if m: out.append(m.group(1))
    except FileNotFoundError: pass
    return out
seen=set(); stack=['AlgebraicJacobian.RiemannRoch.ChiLedger']
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for i in imports(path(m)):
        if i not in seen: stack.append(i)
tot=0;sor=0;files=0
for m in sorted(seen):
    p=path(m)
    if os.path.exists(p):
        files+=1
        t=open(p).read(); tot+=t.count('\n')
        sor+=len(re.findall(r'(?<![\w.])sorry(?![\w])',t))
print(f'ChiLedger closure: {files} files, {tot} lines, {sor} sorry tokens')
